def _mode(cfg):
    return report_cfg(cfg).get("thermal", {}).get("mode", "unknown")


def _labels(mode):
    if mode == "radiative_equilibrium":
        return dict(wall="Radiative-equilibrium wall temperature", model="steady_radiative_equilibrium_planar_CFD",
                    short="radiative_equilibrium", title="steady radiative-equilibrium CFD",
                    boundary="Gas-to-wall heat transfer balances external radiation; equilibrium wall temperature is solved.",
                    interpretation="Equilibrium surface temperature and separate fluid-side static samples. Separate Mechanical loading determines the transient solid response; this steady CFD field has no physical-time solid history.")
    return dict(wall="Adiabatic wall / recovery temperature", model="steady_adiabatic_planar_CFD",
                short="adiabatic", title="steady adiabatic CFD",
                boundary="q_wall = 0; no radiation or imposed wall temperature",
                interpretation="Gas/recovery temperatures; no solid thermal history or material-temperature prediction.")


def _clear_generated(directory, filenames):
    for name in filenames:
        (Path(directory) / name).unlink(missing_ok=True)


def report_cfg(cfg):
    """Use recovery-state physics while keeping reports in the nose directory."""
    if cfg.get("workflow", {}).get("strategy") != "two_endpoint":
        return cfg
    result = copy.deepcopy(cfg)
    work = Path(cfg.get("_study_work_dir", cfg["project"]["work_dir"]))
    result["project"]["work_dir"] = str(work)
    result["thermal"] = {"mode": "adiabatic"}
    directory = Path(cfg.get("temperature_export",{}).get("output_directory","temperature"))
    result.setdefault("temperature_export", {})["output_directory"] = str(directory if directory.is_absolute() else work/directory)
    return result


def source_work(cfg):
    """The source solution lives inside an endpoint folder in the restored study."""
    work = Path(cfg.get("_study_work_dir", cfg["project"]["work_dir"]))
    return work / "cfd/adiabatic" if cfg.get("workflow", {}).get("strategy") == "two_endpoint" else work


def source_cfg(cfg):
    result = copy.deepcopy(report_cfg(cfg))
    result["project"]["work_dir"] = str(source_work(cfg))
    return result


def _single_source_current(cfg):
    """Match the saved radiating solution to the actual CAD and mesh bytes."""
    work = source_work(cfg)
    summary = read_json(work / "summary.json")
    return (summary.get("thermal_mode") == "radiative_equilibrium" and
            summary.get("source_geometry_sha256") == file_sha256(cfg["geometry"]["input_file"]) and
            summary.get("source_mesh_sha256") == file_sha256(work / "02_mesh.msh.h5"))


def aero_complete_for_report(cfg):
    """Endpoint forces are stored at the nose root but come from adiabatic CFD."""
    work = Path(cfg.get("_study_work_dir", cfg["project"]["work_dir"]))
    if cfg.get("workflow", {}).get("strategy") != "two_endpoint":
        if not aero_complete(work, cfg):return False
        if _mode(cfg) != "radiative_equilibrium":return True
        try:
            return (_single_source_current(cfg) and read_aero(work).get("source_sha256") == {
                "final_case": file_sha256(work / "04_final.cas.h5"),
                "final_data": file_sha256(work / "04_final.dat.h5")})
        except (OSError, ValueError, KeyError, TypeError):return False
    result = read_aero(work)
    if result.get("status") != "complete" or result.get("model_version") != AERO_MODEL_VERSION:
        return False
    if any(result.get(key) != value for key, value in reference_state(report_cfg(cfg)).items()):
        return False
    base = cfg["geometry"].get("body_wall_name", "body_wall")
    zones = result.get("body_wall_zones", [])
    if not zones or any(zone != base and not zone.startswith(base + ".") for zone in zones):
        return False
    from .force_history import assess_saved_force_history
    if result.get("force_stability") != assess_saved_force_history(source_cfg(cfg)):
        return False
    try:
        source = source_work(cfg)
        recorded = result.get("source_sha256")
        expected = {"final_case": file_sha256(source / "04_final.cas.h5"),
                    "final_data": file_sha256(source / "04_final.dat.h5")}
        if recorded is not None:
            return recorded == expected
        saved = (work / "aero_summary.json").stat().st_mtime_ns
        return all((source / name).stat().st_mtime_ns <= saved
                   for name in ("04_final.cas.h5", "04_final.dat.h5"))
    except OSError:
        return False


def temperature_complete(cfg):
    try:
        cfg = report_cfg(cfg)
        mode = _mode(cfg)
        if mode not in {"adiabatic", "radiative_equilibrium"}:
            return False
        csv_path, summary_path = temperature_paths(cfg)
        summary = read_json(summary_path)
        if summary.get("status") != "complete" or summary.get("thermal_mode") != mode:
            return False
        if mode == "radiative_equilibrium":
            from .solution_quality import saved_quality
            if saved_quality(source_cfg(cfg))["status"] != "residual_screen_passed":
                return False
            nodes = summary.get("wall_nodes", {})
            if (not _single_source_current(cfg) or nodes.get("status") != "complete" or
                    nodes.get("csv_sha256") != file_sha256(csv_path.parent / "wall_temperature_nodes.csv")):
                return False
        work = source_work(cfg)
        return (summary.get("temperature_export_signature") == cfg.get("temperature_export", {}) and
                summary.get("conditions") == temperature_conditions(cfg) and
                summary.get("wall_csv_sha256") == file_sha256(csv_path) and
                summary.get("source_sha256") == {
                    "final_case": file_sha256(work / "04_final.cas.h5"),
                    "final_data": file_sha256(work / "04_final.dat.h5")})
    except (OSError, ValueError, KeyError, TypeError, AttributeError):
        return False


def build_gas_row(cfg, status="complete", elapsed_s=0, error=""):
    """A failed case still produces a row, even if its configuration is invalid."""
    summary, aero, fresh_temp, fresh_aero = {}, {}, False, False
    problems = []
    project = cfg.get("project", {}) if isinstance(cfg, dict) else {}
    if not isinstance(project, dict):
        project = {}
    try:
        gas_cfg = report_cfg(cfg)
        _, summary_path = temperature_paths(gas_cfg)
        summary = read_json(summary_path)
        work = Path(gas_cfg["project"]["work_dir"])
        aero = read_aero(work)
        fresh_temp = temperature_complete(cfg)
        # Validate before aero_complete's early cache-status return so invalid
        # reference settings are reported consistently for failed batch cases.
        reference_state(gas_cfg)
        fresh_aero = aero_complete_for_report(cfg)
        from .solution_quality import saved_quality
        quality = saved_quality(source_cfg(cfg))
        if quality["status"] == "failed":
            status = "unconverged"
            problems.extend(quality.get("reasons",[]))
    except (OSError, ValueError, KeyError, TypeError, AttributeError) as exc:
        problems.append(str(exc))
        status = "failed"
    if problems:
        error = "; ".join(part for part in (error, *problems) if part)
    def metric(section, key):
        values = summary.get(section, {})
        return values.get(key) if fresh_temp and isinstance(values, dict) else None
    return dict(case=project.get("name", "unknown"), status=status, thermal_mode=_mode(cfg),
        temperature_status="complete" if fresh_temp else "missing_or_stale",
        aero_status="complete" if fresh_aero else "missing_or_stale", error=error, elapsed_s=round(elapsed_s, 3),
        maximum_wall_temperature_K=metric("wall_temperature", "maximum_K"),
        mean_wall_temperature_K=metric("wall_temperature", "length_weighted_mean_K"),
        maximum_near_wall_fluid_temperature_K=metric("near_wall_fluid_temperature", "maximum_K"),
        mean_near_wall_fluid_temperature_K=metric("near_wall_fluid_temperature", "length_weighted_mean_K"),
        **aero_report_fields(aero if fresh_aero else {}),
        convergence_status="failed" if status == "unconverged" else (aero.get("convergence_status", "not_verified") if fresh_aero else "not_verified"))


def profile(rows, cfg):
    """Rotate ordered wall-face samples to back → nose → back for comparisons."""
    if len(rows) < 3:
        raise ValueError("At least three ordered wall samples are required")
    direction = np.asarray(cfg.get("reporting", {}).get("nose_direction", [1, 0]), dtype=float)
    if direction.shape != (2,) or not np.isfinite(direction).all() or np.linalg.norm(direction) == 0:
        raise ValueError("reporting.nose_direction must be a finite nonzero XY vector")
    xy = np.asarray([[float(row["x_m"]), float(row["y_m"])] for row in rows])
    if not np.isfinite(xy).all():
        raise ValueError("Wall coordinates must be finite")
    along = xy @ direction
    start = min(range(len(rows)), key=lambda i: (along[i], xy[i, 1], xy[i, 0]))
    rows = rows[start:] + rows[:start]
    xy = np.roll(xy, -start, axis=0)
    nose = int(np.argmax(xy @ direction))
    arc = np.concatenate(([0.0], np.cumsum(np.linalg.norm(np.diff(xy, axis=0), axis=1))))
    total = arc[-1] + float(np.linalg.norm(xy[-1] - xy[0]))
    if arc[nose] <= 0 or total <= arc[nose]:
        raise ValueError("Cannot normalize back → nose → back profile")
    positions = np.where(arc <= arc[nose], 0.5 * arc / arc[nose],
                         0.5 + 0.5 * (arc - arc[nose]) / (total - arc[nose]))
    return [dict(row, design=cfg["project"]["name"], s_profile_m=float(distance), s_norm=float(position))
            for row, distance, position in zip(rows, arc, positions)]


def _save(fig, target, plt):
    fig.tight_layout()
    fig.savefig(target, dpi=160)
    plt.close(fig)
    return str(target)


def _temperature_range(records, column):
    values = np.asarray([float(row[column]) for row in records])
    if not len(values) or not np.isfinite(values).all() or np.any(values <= 0):
        raise ValueError(f"Invalid {column} values")
    low, high = float(values.min()), float(values.max())
    # A constant-temperature surface must still have a useful color scale.
    if low == high:
        padding = max(1.0, abs(low) * 0.005)
        return low - padding, high + padding
    return low, high


def _wall_map(ax, values, column, label, limits, cmap="inferno"):
    xy = np.asarray([[float(row["x_m"]), float(row["y_m"])] for row in values])
    closed = np.vstack((xy, xy[0]))
    ax.plot(closed[:, 0], closed[:, 1], color="0.45", linewidth=0.7, zorder=1)
    scatter = ax.scatter(xy[:, 0], xy[:, 1], c=[float(row[column]) for row in values],
                         s=20, cmap=cmap, vmin=limits[0], vmax=limits[1], zorder=2)
    ax.set(xlabel="x [m]", ylabel="y [m]", title=label)
    ax.set_aspect("equal", adjustable="box")
    ax.grid(alpha=0.15)
    return scatter


def _read_nodes(summary, wall_csv, warnings, case):
    node_info = summary.get("fluid_nodes", {})
    if not isinstance(node_info, dict) or node_info.get("status") != "complete":
        reason = node_info.get("error", "not exported") if isinstance(node_info, dict) else "invalid summary"
        warnings.append(f"{case}: optional fluid-node map unavailable ({reason})")
        return []
    try:
        # The exporter places this optional file next to the mandatory wall CSV.
        points = read_csv(wall_csv.parent / "fluid_temperature_nodes.csv")
        xyz = np.asarray([[float(point[key]) for key in ("x_m", "y_m", "z_m")] for point in points])
        temperatures = np.asarray([float(point["static_temperature_K"]) for point in points])
        if (len(points) != node_info.get("point_count") or not len(points) or not np.isfinite(xyz).all()
                or not np.isfinite(temperatures).all() or np.any(temperatures <= 0)
                or np.any(abs(xyz[:, 2]) > 1e-7)):
            raise ValueError("Fluid-node data do not match a valid planar temperature export")
        return points
    except (OSError, ValueError, KeyError, TypeError) as exc:
        warnings.append(f"{case}: optional fluid-node map unavailable ({exc})")
        return []


def _read_history(work, temperature_summary, warnings, case):
    """Read saved CFD iteration samples only when they belong to this solution."""
    solver_summary = read_json(work / "summary.json")
    if solver_summary.get("thermal_mode") not in {"adiabatic", "radiative_equilibrium"}:
        return []
    metadata = solver_summary.get("temperature_history", {})
    if not isinstance(metadata, dict) or metadata.get("status") not in {"complete", "partial"}:
        return []
    try:
        path = work / "solver_temperature_history.csv"
        if (metadata.get("csv_sha256") != file_sha256(path)
                or metadata.get("source_sha256") != temperature_summary.get("source_sha256")):
            raise ValueError("Iteration history does not belong to the current saved solution")
        history = read_csv(path)
        if len(history) < 2:
            raise ValueError("Fewer than two iteration samples; no convergence curve is available")
        previous = -1
        for row in history:
            iteration = float(row["iteration"])
            values = [float(row[key]) for key in (
                "wall_temperature_min_k", "wall_temperature_avg_k", "wall_temperature_max_k")]
            if (not np.isfinite(iteration) or not iteration.is_integer() or iteration <= previous
                    or not np.isfinite(values).all() or values[0] <= 0
                    or not values[0] <= values[1] <= values[2]):
                raise ValueError("Invalid wall-temperature iteration samples")
            row["iteration"] = int(iteration)
            previous = iteration
        if metadata["status"] == "partial":
            warnings.append(f"{case}: temperature convergence history is partial")
        return history
    except (OSError, ValueError, KeyError, TypeError) as exc:
        warnings.append(f"{case}: temperature convergence figure unavailable ({exc})")
        return []


def _read_force_history(cfg, warnings, case):
    """Return source-verified native-iteration totals, never physical time."""
    from .force_history import read_saved_force_history
    try:
        history, _ = read_saved_force_history(source_cfg(cfg))
        if len(history) < 2:
            raise ValueError("Fewer than two native iteration samples")
        return history
    except (OSError, ValueError, KeyError, TypeError) as exc:
        warnings.append(f"{case}: force iteration history unavailable ({exc})")
        return []


def _force_case_report(case, plt):
    """Write force diagnostics even when no temperature figure can be made."""
    name, work, rows, row = case["name"], case["work"], case["history"], case["row"]
    directory = work / "reports"
    directory.mkdir(parents=True, exist_ok=True)
    files = {}
    if rows:
        files["force_iteration_history_csv"] = str(write_csv(directory / "force_iteration_history.csv", rows))
        fig, ax = plt.subplots(figsize=(9, 5))
        for column, label in (("drag_per_unit_span_N_m", "Drag"), ("lift_per_unit_span_N_m", "Lift")):
            ax.plot([sample["iteration"] for sample in rows],
                    [float(sample[column]) for sample in rows], label=label)
        ax.set(xlabel="Native Fluent iteration (no physical time)", ylabel="Total force per unit span [N/m]",
               title=name + " — whole-body forces; stability: " + row["force_stability_status"])
        ax.legend()
        ax.grid(alpha=.3)
        files["force_iteration_history"] = _save(fig, directory / "force_iteration_history.png", plt)
    metadata = dict(case=name, model="steady_planar_whole_body_forces", files=files,
                    force_stability_status=row["force_stability_status"],
                    component_status=row["component_status"],
                    force_history_samples=len(rows),
                    interpretation="Signed drag and lift projected in the configured freestream basis; native CFD iterations are not physical time.",
                    limitation="Force stability alone does not establish residual convergence, mesh independence, or whole-vehicle performance.")
    path = directory / "force_iteration_report.json"
    path.write_text(json.dumps(metadata, indent=2), encoding="utf-8")
    files["force_iteration_report"] = str(path)
    return files


def _force_comparison(cases, rows, output_dir, comparable, plt):
    """Retain all dimensional records, with checks visible alongside them."""
    columns = ["case", "status", "aero_status", *aero_report_fields({}), "convergence_status"]
    records = [{column: row.get(column) for column in columns} for row in rows]
    files = {"aerodynamic_comparison_csv": str(write_csv(output_dir / "aerodynamic_comparison.csv", records,
                                                         fields=columns))}
    history = [dict(case=case["name"], force_stability_status=case["row"]["force_stability_status"], **sample)
               for case in cases for sample in case["history"]]
    fields = ["case", "force_stability_status", "iteration", "drag_per_unit_span_N_m", "lift_per_unit_span_N_m"]
    files["force_iteration_history_comparison_csv"] = str(write_csv(
        output_dir / "force_iteration_history_comparison.csv", history, fields=fields))
    with_history = [case for case in cases if case["history"]]
    if comparable and with_history:
        fig, ax = plt.subplots(figsize=(10, 5))
        for case in with_history:
            samples = case["history"]
            label = case["name"] + " [" + case["row"]["force_stability_status"] + "]"
            line, = ax.plot([sample["iteration"] for sample in samples],
                            [float(sample["drag_per_unit_span_N_m"]) for sample in samples], label=label + " drag")
            ax.plot([sample["iteration"] for sample in samples],
                    [float(sample["lift_per_unit_span_N_m"]) for sample in samples], linestyle="--",
                    color=line.get_color(), label=label + " lift")
        ax.set(xlabel="Native Fluent iteration (no physical time)", ylabel="Total force per unit span [N/m]",
               title="Whole-body force convergence (solid = drag; dashed = lift)")
        ax.legend()
        ax.grid(alpha=.3)
        files["force_iteration_history_comparison"] = _save(
            fig, output_dir / "force_iteration_history_comparison.png", plt)
    complete = [row for row in rows if row.get("aero_status") == "complete"
                and row.get("component_status") == "complete"]
    if comparable and complete:
        fig, ax = plt.subplots(figsize=(max(8, len(complete) * 1.2), 5))
        indices = np.arange(len(complete))
        for offset, (column, label) in enumerate((("drag_per_unit_span_N_m", "Total"),
                ("pressure_drag_per_unit_span_N_m", "Pressure"), ("viscous_drag_per_unit_span_N_m", "Viscous"))):
            ax.bar(indices + (offset - 1) * .25, [row[column] for row in complete], width=.25, label=label)
        ax.set_xticks(indices, [row["case"] + "\n[" + row["force_stability_status"] + "]" for row in complete],
                      rotation=25, ha="right")
        ax.set(ylabel="Sectional drag [N/m]", title="Whole-body drag components — force stability shown per case")
        ax.legend()
        ax.grid(axis="y", alpha=.3)
        files["drag_components_comparison"] = _save(fig, output_dir / "drag_components_comparison.png", plt)
    return files


def _read_convection(cfg, warnings, case):
    if cfg.get("workflow", {}).get("strategy") != "two_endpoint":
        return []
    from .endpoint_loading import verify_convection_package
    from .thermal_loading import ThermalAnalysisError
    try:
        path, _ = verify_convection_package(cfg)
        rows = profile(read_csv(path), report_cfg(cfg))
        coefficients = np.asarray([float(row["heat_transfer_coefficient_W_m2K"]) for row in rows])
        if not np.isfinite(coefficients).all() or np.any(coefficients < 0):
            raise ValueError("Derived convection coefficients must be finite and nonnegative")
        return rows
    except (OSError, ValueError, KeyError, TypeError, ThermalAnalysisError) as exc:
        warnings.append(f"{case}: derived convection plots unavailable ({exc})")
        return []


def _case_figures(case, temperature_ranges, plt):
    cfg, values, summary, points = case["cfg"], case["values"], case["summary"], case["nodes"]
    report_dir, name = case["work"] / "reports", cfg["project"]["name"]
    labels = _labels(_mode(cfg))
    report_dir.mkdir(parents=True, exist_ok=True)
    files = {"temperature_profile_csv": str(write_csv(report_dir / "temperature_profile.csv", values))}
    for coordinate, xlabel, filename in (
            ("s_norm", "Normalized wall position, back → nose → back", "temperature_profile.png"),
            ("s_profile_m", "Distance along wall-face samples [m]", "wall_temperature_vs_position.png")):
        fig, ax = plt.subplots(figsize=(9, 5))
        for column, label in (("wall_temperature_K", labels["wall"]),
                              ("near_wall_fluid_temperature_K", "Fluid-side surface values")):
            ax.plot([row[coordinate] for row in values], [float(row[column]) for row in values], label=label)
        ax.set(xlabel=xlabel, ylabel="Temperature [K]", title=name + " — " + labels["title"])
        if coordinate == "s_norm":
            ax.set_xlim(0, 1)
        ax.grid(alpha=0.3)
        ax.legend()
        files[filename[:-4]] = _save(fig, report_dir / filename, plt)
    for column, title, filename in (
            ("wall_temperature_K", labels["wall"], labels["short"] + "_wall_temperature_map.png"),
            ("near_wall_fluid_temperature_K", "Fluid-side static temperature (surface samples)", "near_wall_fluid_temperature_map.png")):
        fig, ax = plt.subplots(figsize=(10, 4))
        scatter = _wall_map(ax, values, column, name + " — " + title, temperature_ranges[column])
        fig.colorbar(scatter, ax=ax, label="Temperature [K]")
        files[filename[:-4]] = _save(fig, report_dir / filename, plt)
    xy = np.asarray([[float(row["x_m"]), float(row["y_m"])] for row in values])
    fig, ax = plt.subplots(figsize=(10, 4))
    closed = np.vstack((xy, xy[0]))
    ax.plot(closed[:, 0], closed[:, 1], label="Ordered CFD wall-face samples")
    ax.scatter(xy[:, 0], xy[:, 1], s=12)
    ax.set(xlabel="x [m]", ylabel="y [m]", title=name + " — wall boundary sampling")
    ax.set_aspect("equal", adjustable="box")
    ax.legend()
    files["wall_boundary"] = _save(fig, report_dir / (labels["short"] + "_wall_boundary.png"), plt)
    if points:
        node_xy = np.asarray([[float(point["x_m"]), float(point["y_m"])] for point in points])
        temperature = np.asarray([float(point["static_temperature_K"]) for point in points])
        node_limits = _temperature_range(points, "static_temperature_K")
        margin = max(float(np.ptp(xy, axis=0).max()) * 0.1, 1e-8)
        low, high = xy.min(axis=0) - margin, xy.max(axis=0) + margin
        near_wall = np.all((node_xy >= low) & (node_xy <= high), axis=1)
        for mask, filename, title in (
                (np.ones(len(points), dtype=bool), "fluid_temperature_nodes.png", "Fluid static temperatures at mesh nodes"),
                (near_wall, "fluid_temperature_near_wall.png", "Fluid mesh temperatures around the wall")):
            if not mask.any():
                continue
            fig, ax = plt.subplots(figsize=(10, 5))
            scatter = ax.scatter(node_xy[mask, 0], node_xy[mask, 1], c=temperature[mask], s=5,
                                 cmap="inferno", vmin=node_limits[0], vmax=node_limits[1])
            ax.plot(closed[:, 0], closed[:, 1], color="cyan", linewidth=0.8, label="Wall-face sample outline")
            ax.set(xlabel="x [m]", ylabel="y [m]", title=name + " — " + title)
            if filename == "fluid_temperature_near_wall.png":
                ax.set_xlim(low[0], high[0])
                ax.set_ylim(low[1], high[1])
            ax.set_aspect("equal", adjustable="box")
            ax.legend(loc="best")
            fig.colorbar(scatter, ax=ax, label="Static gas temperature [K]")
            files[filename[:-4]] = _save(fig, report_dir / filename, plt)
    if case["history"]:
        fig, ax = plt.subplots(figsize=(9, 5))
        for column, label in (("wall_temperature_min_k", "Minimum"),
                              ("wall_temperature_avg_k", "Mean"),
                              ("wall_temperature_max_k", "Maximum")):
            ax.plot([row["iteration"] for row in case["history"]],
                    [float(row[column]) for row in case["history"]], label=label, marker=".")
        ax.set(xlabel="Fluent iteration", ylabel=labels["wall"] + " [K]",
               title=name + " — CFD temperature convergence (no physical time)")
        ax.legend()
        ax.grid(alpha=0.3)
        files["temperature_convergence"] = _save(fig, report_dir / "temperature_convergence.png", plt)
    convection = case.get("convection", [])
    if convection:
        column = "heat_transfer_coefficient_W_m2K"
        files["derived_h_profile_csv"] = str(write_csv(report_dir / "derived_h_profile.csv", convection))
        fig, ax = plt.subplots(figsize=(9, 5))
        ax.plot([row["s_norm"] for row in convection], [float(row[column]) for row in convection])
        ax.set(xlabel="Normalized wall position, back → nose → back", ylabel="h [W/(m² K)]",
               title=name + " — cold-wall calibrated convection coefficient", xlim=(0, 1))
        ax.grid(alpha=0.3)
        files["derived_h_profile"] = _save(fig, report_dir / "derived_h_profile.png", plt)
        coefficients = [float(row[column]) for row in convection]
        low, high = min(coefficients), max(coefficients)
        limits = (low, high if high > low else high + max(1., high * 0.005))
        fig, ax = plt.subplots(figsize=(10, 4))
        scatter = _wall_map(ax, convection, column, name + " — spatial convection input", limits, cmap="viridis")
        fig.colorbar(scatter, ax=ax, label="h [W/(m² K)]")
        files["derived_h_map"] = _save(fig, report_dir / "derived_h_map.png", plt)
        # Signed cold-wall face flux projected to vertices is calibration data,
        # distinct from Mechanical's changing convection/radiation load.
        column = "cold_heat_flux_into_wall_W_m2"
        fig, ax = plt.subplots(figsize=(9,5))
        ax.plot([row["s_profile_m"] for row in convection],[float(row[column]) for row in convection])
        ax.set(xlabel="Distance along wall [m]",ylabel="Calibration heat flux into wall [W/m²]",
               title=name+" — cold-wall reference (face values projected to vertices)")
        ax.grid(alpha=.3)
        files["cold_wall_heat_flux_profile"] = _save(fig,report_dir/"cold_wall_heat_flux_profile.png",plt)
        flux = [float(row[column]) for row in convection]
        low, high = min(flux),max(flux)
        limits = (low, high if high > low else high+max(1.,abs(high)*.005))
        fig, ax = plt.subplots(figsize=(10,4))
        scatter = _wall_map(ax,convection,column,name+" — cold-wall calibration heat flux",limits,cmap="viridis")
        fig.colorbar(scatter,ax=ax,label="Calibration heat flux into wall [W/m²]")
        files["cold_wall_heat_flux_map"] = _save(fig,report_dir/"cold_wall_heat_flux_map.png",plt)
    manifest = dict(model=labels["model"], files=files,
                    wall_boundary_condition=labels["boundary"], interpretation=labels["interpretation"],
                    temperature_color_ranges_K=temperature_ranges, sampling=summary.get("sampling", {}),
                    spatial_method="Temperature-colored samples; no interpolation across the vehicle interior.",
                    convergence_history_samples=len(case["history"]),
                    convection="Cold-wall calibrated spatial h, held constant as the solid warms." if convection else "No convection coefficient is derived by this model.",
                    history="Steady CFD has no physical time history or transient solid temperature field.")
    target = report_dir / (labels["short"] + "_case_report.json")
    target.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    return files


def _comparison_maps(cases, column, label, filename, limits, output_dir, plt):
    columns = min(3, len(cases))
    row_count = (len(cases) + columns - 1) // columns
    fig, axes = plt.subplots(row_count, columns, figsize=(6 * columns, 3.5 * row_count), squeeze=False)
    for ax, case in zip(axes.flat, cases):
        scatter = _wall_map(ax, case["values"], column, case["cfg"]["project"]["name"], limits)
    for ax in list(axes.flat)[len(cases):]:
        ax.set_visible(False)
    fig.suptitle(label + " — common temperature scale")
    fig.colorbar(scatter, ax=list(axes.flat)[:len(cases)], label="Temperature [K]", shrink=0.8)
    # A shared colorbar has its own layout; constrained margins avoid tight_layout warnings.
    fig.subplots_adjust(left=0.07, right=0.84, bottom=0.14, top=0.84, hspace=0.5, wspace=0.35)
    target = output_dir / filename
    fig.savefig(target, dpi=160)
    plt.close(fig)
    return str(target)


def create_gas_reports(runs_dir, output_dir):
    """Create data-backed gas plots without launching Fluent or a solid solver."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from .study import BatchError, validate_stage_outputs, stage_files

    runs_dir, output_dir = Path(runs_dir), Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    _clear_generated(output_dir, COMPARISON_ARTIFACTS)
    rows, cases, conditions, warnings = [], [], set(), []
    force_cases, force_conditions = [], set()
    for work in sorted(runs_dir.iterdir()) if runs_dir.is_dir() else []:
        if not work.is_dir():
            continue
        _clear_generated(work / "reports", CASE_ARTIFACTS)
        path = work / "_batch/config.yaml"
        if not path.is_file():
            continue
        row = None
        try:
            cfg = load_yaml(path)
            if _mode(cfg) not in {"adiabatic", "radiative_equilibrium"}:
                continue
            cfg.setdefault("project", {})["work_dir"] = str(work.resolve())
            cfg["project"].setdefault("name", work.name)
            row = build_gas_row(cfg)
            rows.append(row)
            if row["aero_status"] == "complete":
                force_cases.append(dict(name=cfg["project"]["name"], work=work, row=row,
                    history=_read_force_history(cfg, warnings, work.name)))
                force_conditions.add(comparison_key(reference_state(report_cfg(cfg)),
                    json.dumps(cfg.get("mesh", {}), sort_keys=True)))
            if row["status"] in ("failed","unconverged"):
                warnings.append(f"{work.name}: {row['error']}")
                continue
            if row["temperature_status"] != "complete" or row["aero_status"] != "complete":
                row["status"] = "incomplete"
            if row["temperature_status"] != "complete":
                warnings.append(f"{work.name}: missing or stale {_mode(cfg)} temperature export")
                continue
            gas_cfg = report_cfg(cfg)
            validate_stage_outputs("temperature_export", stage_files(work, gas_cfg)["temperature_export"])
            wall_csv, summary_path = temperature_paths(gas_cfg)
            values = profile(read_csv(wall_csv), gas_cfg)
            for column in ("wall_temperature_K", "near_wall_fluid_temperature_K"):
                _temperature_range(values, column)
            summary = read_json(summary_path)
            weights = [float(value["segment_length_m"]) for value in values]
            for prefix, column in (("wall", "wall_temperature_K"),
                                   ("near_wall_fluid", "near_wall_fluid_temperature_K")):
                temperatures = [float(value[column]) for value in values]
                row[f"maximum_{prefix}_temperature_K"] = max(temperatures)
                row[f"mean_{prefix}_temperature_K"] = float(np.average(temperatures, weights=weights))
            case = dict(cfg=gas_cfg, work=work, values=values, summary=summary,
                        nodes=_read_nodes(summary, wall_csv, warnings, work.name), row=row,
                        history=_read_history(source_work(cfg), summary, warnings, work.name),
                        convection=_read_convection(cfg, warnings, work.name))
            cases.append(case)
            conditions.add(comparison_key(reference_state(gas_cfg), json.dumps(cfg.get("mesh", {}), sort_keys=True)))
        except (ValueError, KeyError, OSError, TypeError, AttributeError, BatchError, yaml.YAMLError) as exc:
            if row is None:
                rows.append(dict(case=work.name, status="invalid_export", thermal_mode=_mode(cfg), error=str(exc)))
            else:
                row["status"] = "invalid_export"
                row["error"] = str(exc)
            warnings.append(f"{work.name}: {exc}")
    comparable = len(conditions) <= 1
    if not comparable:
        warnings.append("Comparison plots withheld: flight, physics, reference or mesh settings differ between cases.")
    profiles = [row for case in cases for row in case["values"]]
    common_ranges = {column: _temperature_range(profiles, column) for column in (
        "wall_temperature_K", "near_wall_fluid_temperature_K")} if profiles and comparable else {}
    case_outputs = {case["name"]: _force_case_report(case, plt) for case in force_cases}
    for case in cases:
        limits = common_ranges or {column: _temperature_range(case["values"], column) for column in (
            "wall_temperature_K", "near_wall_fluid_temperature_K")}
        case_outputs.setdefault(case["cfg"]["project"]["name"], {}).update(_case_figures(case, limits, plt))
    modes = {row.get("thermal_mode") for row in rows}
    labels = _labels("radiative_equilibrium" if "radiative_equilibrium" in modes else "adiabatic")
    mixed = len(modes) > 1
    summary_name = "temperature_summary.csv" if mixed else labels["short"] + "_temperature_summary.csv"
    profiles_name = "temperature_profiles.csv" if mixed else labels["short"] + "_temperature_profiles.csv"
    created = {"temperature_summary": str(write_csv(output_dir / summary_name, rows,
        fields=list(dict.fromkeys(key for row in rows for key in row)) if rows else ["case", "status", "thermal_mode"]))}
    created["temperature_profiles"] = str(write_csv(output_dir / profiles_name, profiles,
        fields=list(profiles[0]) if profiles else ["design", "s_norm", "wall_temperature_K", "near_wall_fluid_temperature_K"]))
    created.update(_force_comparison(force_cases, rows, output_dir, len(force_conditions) <= 1, plt))
    if comparable and profiles:
        from .temperature_comparison import steady_temperature_bars
        temperature_bars = steady_temperature_bars(cases, output_dir, plt)
        created.update(temperature_bars)
        for key, path in temperature_bars.items():
            if key.endswith("_png"):
                print(f"[report] Saved raw maximum-temperature comparison: {path}")
        with_convection = [case for case in cases if case["convection"]]
        if with_convection:
            fig, ax = plt.subplots(figsize=(10, 5))
            for case in with_convection:
                ax.plot([row["s_norm"] for row in case["convection"]],
                        [float(row["heat_transfer_coefficient_W_m2K"]) for row in case["convection"]],
                        label=case["cfg"]["project"]["name"])
            ax.set(xlabel="Normalized wall position, back → nose → back", ylabel="h [W/(m² K)]",
                   title="Cold-wall calibrated spatial convection coefficients", xlim=(0, 1))
            ax.legend()
            ax.grid(alpha=0.3)
            created["heat_transfer_coefficient_comparison"] = _save(
                fig, output_dir / "heat_transfer_coefficient_comparison.png", plt)
        for column, label in (("wall_temperature_K", labels["wall"]),
                              ("near_wall_fluid_temperature_K", "Fluid-side static temperature (surface samples)")):
            fig, ax = plt.subplots(figsize=(10, 5))
            for case in cases:
                selected = case["values"]
                ax.plot([row["s_norm"] for row in selected], [float(row[column]) for row in selected],
                        label=case["cfg"]["project"]["name"])
            ax.set(xlabel="Normalized wall position, back → nose → back", ylabel="Temperature [K]",
                   title=label + " comparison", xlim=(0, 1))
            ax.legend()
            ax.grid(alpha=0.3)
            created[column + "_comparison"] = _save(fig, output_dir / (column + "_comparison.png"), plt)
            map_name = "wall_temperature_maps_comparison.png" if column == "wall_temperature_K" else "near_wall_fluid_temperature_maps_comparison.png"
            created[column + "_maps_comparison"] = _comparison_maps(
                cases, column, label, map_name, common_ranges[column], output_dir, plt)
        fig, ax = plt.subplots(figsize=(max(9, len(cases) * 1.5), 5))
        indices = np.arange(len(cases))
        for offset, (metric, label) in enumerate((
                ("maximum_wall_temperature_K", "Maximum wall"),
                ("mean_wall_temperature_K", "Mean wall"),
                ("maximum_near_wall_fluid_temperature_K", "Maximum fluid-side"),
                ("mean_near_wall_fluid_temperature_K", "Mean fluid-side"))):
            ax.bar(indices + (offset - 1.5) * 0.2, [case["row"][metric] for case in cases], width=0.2, label=label)
        ax.set_xticks(indices, [case["cfg"]["project"]["name"] for case in cases], rotation=25, ha="right")
        ax.set(ylabel="Temperature [K]", title=labels["title"] + " temperature comparison (means weighted by wall length)")
        ax.legend()
        ax.grid(axis="y", alpha=0.3)
        created["temperature_statistics_comparison"] = _save(fig, output_dir / "gas_temperature_statistics_comparison.png", plt)
        with_history = [case for case in cases if case["history"]]
        if with_history:
            fig, ax = plt.subplots(figsize=(10, 5))
            for case in with_history:
                iterations = [row["iteration"] for row in case["history"]]
                name = case["cfg"]["project"]["name"]
                line, = ax.plot(iterations, [float(row["wall_temperature_max_k"]) for row in case["history"]],
                                label=name + " maximum")
                ax.plot(iterations, [float(row["wall_temperature_avg_k"]) for row in case["history"]],
                        linestyle="--", color=line.get_color(), label=name + " mean")
            ax.set(xlabel="Fluent iteration", ylabel=labels["wall"] + " [K]",
                   title="CFD temperature convergence comparison (solid = max, dashed = mean; no physical time)")
            ax.legend()
            ax.grid(alpha=0.3)
            created["temperature_convergence_comparison"] = _save(
                fig, output_dir / "temperature_convergence_comparison.png", plt)
        complete = [row for row in rows if row["status"] == "complete"]
        if complete:
            fig, ax = plt.subplots(figsize=(8, 5))
            metric = "maximum_wall_temperature_K" if "radiative_equilibrium" in modes else "maximum_near_wall_fluid_temperature_K"
            for row in complete:
                ax.scatter(row["drag_per_unit_span_N_m"], row[metric],
                           marker="o" if force_screening_eligible(row) else "x")
                ax.annotate(row["case"] + " [" + row["force_stability_status"] + "]",
                            (row["drag_per_unit_span_N_m"], row[metric]))
            ax.set(xlabel="Sectional drag [N/m]", ylabel="Maximum wall temperature [K]" if "radiative_equilibrium" in modes else "Maximum fluid-side surface temperature [K]",
                   title=labels["wall"] + " and drag comparison")
            ax.grid(alpha=0.3)
            filename = "drag_vs_wall_temperature.png" if "radiative_equilibrium" in modes else "drag_vs_near_wall_temperature.png"
            created["drag_vs_temperature"] = _save(fig, output_dir / filename, plt)
    manifest = dict(model=labels["model"], comparable_conditions=comparable,
        warnings=warnings, files=created, case_files=case_outputs,
        temperature_color_ranges_K=common_ranges,
        interpretation=labels["interpretation"],
        sampling="Wall and fluid-side values use wall-face coordinates; fluid-side samples are not a specified offset distance.",
        spatial_method="Colored samples only; no invented temperature interpolation across the solid interior.",
        history="No physical-time history exists in steady CFD. Optional convergence curves use Fluent iterations. Mechanical supplies separate physical-time solid results; historical figures require --reference-dir.",
        force_history="Total whole-body drag/lift use native Fluent iterations, not physical time. Records with failed or unverified stability are retained and labelled; they are not validated design claims.",
        force_comparable_conditions=len(force_conditions) <= 1,
        convergence="Assess residuals, force/temperature stability and mesh sensitivity before CDR conclusions.")
    if mixed:
        manifest.update(model="mixed_steady_planar_CFD",
                        interpretation="Separate models are plotted per case. Cross-model comparisons are withheld.")
    report_name = "steady_temperature_report.json" if mixed else labels["short"] + "_report.json"
    (output_dir / report_name).write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    print(f"[report] {len(rows)} steady CFD case(s); outputs: {output_dir}")
    return rows, created
